struct AppState { var count = 0 }
func counterReducer(action: Action, state: AppState?) -> AppState {
    var state = state ?? AppState()
    switch action {
    case _ as Increment: state.count += 1
    default: break
    }
    return state
}
let mainStore = Store<AppState>(reducer: counterReducer, state: nil)
mainStore.subscribe(self)          // subscriber implements newState(state:)

